    foreach(string script in new[]{"ewar_point_script","ewar_scram_script"}){world.Screen=ViewMode.Station;world.Grid="station";world.Hangar[script]=1;Check(world.LoadEwarPayload(i,script),"focus script fits "+h.Name);world.Screen=ViewMode.Space;world.Grid="belt";world.SystemId="aster";ship.Cap=ship.MaxCap;ship.Position=Vector3.Zero;world.Targets=[new(){Id="focus",Training=true,Kind=TargetKind.Raider,Profile=Ship.RaiderProfile(),Position=new(1000,0,0),Shield=100000,Armor=100000,Hull=100000}];world.SelectedId=world.LockedId="focus";world.Update(ship.Ewar[i].Cooldown+.1f);ship.Cap=ship.MaxCap;world.ToggleEwar(i);world.Update(.1f);Check(world.EwarFor("focus").WarpStrength==10000&&!world.EwarFor("focus").Bubble&&!ship.InterdictionAssistanceBlocked,"targeted infinite focus "+h.Name);Check(world.EwarFor("focus").Scrammed==(script=="ewar_scram_script"),"distinct point and scram "+h.Name);ship.Ewar[i].Stop();world.Update(.1f);world.EwarEffects.Clear();}
   }
