  }
  Ship Hull(string name,int level=5){var s=new Ship();s.ApplyFleetHull(FleetCatalog.Source(name));foreach(int skill in ShipBatch21.ById[s.CombatHull].Traits.Where(t=>t.Skill!=0).Select(t=>t.Skill).Distinct())s.HullProficiency[skill]=level;return s;}
  var medium=DroneCatalog.All.First(d=>!d.Fighter&&d.Kind=="Combat"&&d.Volume==10);var light=DroneCatalog.All.First(d=>!d.Fighter&&d.Kind=="Combat"&&d.Volume==5);Check(Near(medium.Enhanced(Hull("Chameleon")).Packet.Total/medium.Packet.Total,7)&&Near(light.Enhanced(Hull("Chameleon")).Packet.Total/light.Packet.Total,1),"Chameleon medium drone restriction");
  var visible=new DemoWorld();visible.NewGame(0);visible.Screen=ViewMode.Space;visible.Grid="belt";visible.Targets=[new(){Id="observer",Profile=Ship.RaiderProfile(),Position=visible.Player.Position+new Vector3(1000,0,0),Shield=10000,Armor=10000,Hull=10000}];Check(visible.DirectionalScan("observer").Any(c=>c.Id=="player"),"ordinary ship visible to scan");Check(!visible.DirectionalScan("observer",360,100).Any(c=>c.Id=="player"),"scanner respects range");
  var hybrid=WeaponCatalog.All.First(d=>d.Size==2&&d.Family=="Railguns");var ham=WeaponCatalog.All.First(d=>d.Family=="Missile Launcher Heavy Assault");var heavyLauncher=WeaponCatalog.All.First(d=>d.Family=="Missile Launcher Heavy");var field=EwarCatalog.All.First(d=>d.Kind==EwarKind.Field);var neut=EwarCatalog.All.First(d=>d.Kind==EwarKind.Neutralizer&&d.Size==2);var sentry=DroneCatalog.All.First(d=>d.Kind=="Sentry");var heavyDrone=DroneCatalog.All.First(d=>d.Kind=="Combat"&&d.Volume==25);
  Check(Near(Hull("Deimos").HullWeapon(hybrid,"damage"),1.25*1.375)&&Near(Hull("Deimos").HullWeapon(hybrid,"falloff"),1.75),"Deimos independent V weapon factors");
  Check(Near(Hull("Ishtar").SpecificDroneFactor(sentry,"damage"),1.25)&&Near(Hull("Ishtar").SpecificDroneFactor(heavyDrone,"damage"),1.5)&&Near(Hull("Ishtar").SpecificDroneFactor(heavyDrone,"tracking"),1.375),"Ishtar sentry and heavy distinctions");Check(Near(Hull("Ishtar").Stat("droneControlDistance")-Hull("Ishtar",0).Stat("droneControlDistance"),25000),"Ishtar actual control distance");
  Check(Near(Hull("Cerberus").HullWeapon(ham,"missileVelocity"),2)&&Near(Hull("Cerberus").HullWeapon(heavyLauncher,"missileVelocity"),1),"Cerberus velocity only HAM");Check(Near(Hull("Rook").HullWeapon(heavyLauncher,"damage","Kinetic"),1.375)&&Near(Hull("Rook").HullWeapon(heavyLauncher,"damage","EM"),1),"Rook typed kinetic damage");
  Check(Near(Hull("Curse").HullEwar(neut)!.Optimal/neut.Optimal,3)&&Near(Hull("Curse").HullEwar(neut)!.Strength/neut.Strength,2),"Curse V neutralizer reach and drain");Check(Near(Hull("Phobos").HullEwar(field)!.Radius/field.Radius,1.25),"Phobos V field radius");
  var mjd=MobilityCatalog.All.Single(d=>d.Kind=="MJD"&&d.Size==2);Check(Near(Hull("Cobra").HullCpu(mjd.Id),.01)&&Near(Hull("Cobra").HullPower(mjd.Id),.01),"Cobra MJD fit reduction");var cobra=Hull("Cobra");cobra.PilotSecurity=-10;Check(Near(cobra.SecurityTackleRange("Web"),1.75)&&Near(cobra.SecurityTackleRange("Point"),1.375),"Cobra negative security tackle clamps");cobra.PilotSecurity=5;Check(cobra.SecurityTackleRange("Web")==1,"positive security no extra range");
  var entropic=WeaponCatalog.All.First(d=>d.Kind==WeaponKind.Entropic&&d.Size==2);Check(Near(medium.Enhanced(Hull("Cobra")).Packet.Total/medium.Packet.Total,2.5)&&Near(light.Enhanced(Hull("Cobra")).Packet.Total/light.Packet.Total,1),"Cobra medium drone restriction");Check(Near(Hull("Ikitursa").HullWeapon(entropic,"rampMax"),2)&&Near(Hull("Tiamat").HullFlat("weapon","ramp"),3.75),"entropic max and per-cycle ramp");Check(Near(Hull("Tiamat").UtilityFactor("probeStrength"),1.5),"Tiamat live probe factor");var small=WeaponCatalog.All.First(d=>d.Size==1&&d.Kind==WeaponKind.Turret);cobra.PilotSecurity=-10;Check(Near(cobra.HullWeapon(small,"damage"),1),"Cobra tackle security does not boost small weapon damage");Check(ShipBatch21.ById[Hull("Enforcer").CombatHull].Traits.Length==0,"legacy Enforcer has no invented traits");
  var jump=new DemoWorld();jump.NewGame(0);jump.Credits=1000000;jump.SystemId="rook";Check(jump.BoardFleetHull(FleetCatalog.Source("Cobra").Id),"Cobra acquired for jump");jump.Screen=ViewMode.Space;jump.Grid="belt";jump.Targets.Clear();jump.Player.Cap=jump.Player.MaxCap;int ji=Array.FindIndex(jump.Player.Mobility,m=>m.Definition?.Kind=="MJD");Check(ji>=0&&jump.ToggleMobility(ji),"Cobra actual MJD activation");var origin=jump.Player.Position;jump.UpdateMobility(jump.Player.Mobility[ji].CycleLeft+.1f);Check(Vector3.Distance(origin,jump.Player.Position)>10000&&!jump.ToggleMobility(ji),"Cobra actual displacement and cooldown");
  var scan=new DemoWorld();scan.NewGame(0);scan.Screen=ViewMode.Space;scan.Grid="belt";scan.Player.Position=Vector3.Zero;scan.Player.Facing=Vector3.UnitZ;scan.Targets=[new(){Id="immune",Training=true,Kind=TargetKind.Raider,Profile=Hull("Lachesis"),Position=new(0,0,1000),Shield=10000,Armor=10000,Hull=10000},new(){Id="normal",Training=true,Kind=TargetKind.Raider,Profile=Ship.RaiderProfile(),Position=new(0,0,-1000),Shield=10000,Armor=10000,Hull=10000}];Check(!scan.DirectionalScan().Any(c=>c.Id=="immune")&&scan.DirectionalScan().Any(c=>c.Id=="normal"),"scanner filters immune target only");Check(!scan.DirectionalScan("player",30).Any(c=>c.Id=="normal"),"facing cone excludes rear target");Check(scan.CanLock("player","immune"),"combat recon remains targetable");for(int k=0;k<8;k++)scan.ScanProbes.Add(new(){System=scan.SystemId,Payload="ut_probe_combat"});scan.ProbeRange=.25f;scan.ProbeCenter=Vector3.Zero;Check(scan.AnalyzeUtilityProbes(),"combat probe formation analyzes");scan.UpdateUtility(11);Check(scan.UtilitySites.Any(s=>s.TargetId=="immune"&&s.Signal>=99.99f),"real combat recon resolves through combat probes");scan.ProbeSelection=scan.UtilitySites.First(s=>s.TargetId=="immune").Id;Check(scan.WarpUtilitySite()&&scan.SelectedId=="immune"&&scan.Targets.Any(t=>t.Id=="immune"),"resolved target warp preserves actual recon");
  var reject=new DemoWorld();reject.NewGame(0);var paid=ShipBatch21.AdvancedCruisers.First();reject.SystemId=paid.HomeSystem;reject.Credits=0;Check(!reject.BoardFleetHull(paid.ShipId)&&reject.FleetBerths.Count==0,"insufficient purchase atomic");
  string save=Path.Combine(Path.GetTempPath(),"batch27-"+Guid.NewGuid());var previous=Environment.GetEnvironmentVariable("STARLIGHT_SAVE_DIR");try{Environment.SetEnvironmentVariable("STARLIGHT_SAVE_DIR",save);world.Save();var loaded=new DemoWorld();Check(loaded.Load()&&loaded.GrantedFleetHulls.Intersect(ShipBatch21.AdvancedCruisers.Select(p=>p.ShipId)).Count()==36,"all thirty-six ownership restore");foreach(var p in ShipBatch21.AdvancedCruisers){var old=world.Player.CombatHull==p.ShipId?world.Player:world.FleetBerths.Single(b=>b.Ship.CombatHull==p.ShipId).Ship;var copy=loaded.Player.CombatHull==p.ShipId?loaded.Player:loaded.FleetBerths.Single(b=>b.Ship.CombatHull==p.ShipId).Ship;Check(old.Attributes.SequenceEqual(copy.Attributes),"saved attributes "+p.ShipId);Check(JsonSerializer.Serialize(old.Drones)==JsonSerializer.Serialize(copy.Drones),"saved drone bay "+p.ShipId);Check(old.HullProficiency.SequenceEqual(copy.HullProficiency)&&Near(old.PilotSecurity,copy.PilotSecurity),"saved proficiency and security "+p.ShipId);Check(JsonSerializer.Serialize(FittingLayoutModel.Installed(old))==JsonSerializer.Serialize(FittingLayoutModel.Installed(copy)),"saved complete fits "+p.ShipId);}}
  finally{Environment.SetEnvironmentVariable("STARLIGHT_SAVE_DIR",previous);if(Directory.Exists(save))Directory.Delete(save,true);}
